    guard color.count >= 3 else { return color }
    let rgb = unliftSDR(SIMD3<Float>(Float(color[0]), Float(color[1]), Float(color[2])))
    return [rgb.x, rgb.y, rgb.z].map { Double(min(max($0, 0), 1)) } + color.dropFirst(3)
}

/// Sony's and Panasonic's curves read the STORED 10-bit code over 1023,
/// and a video-range file decodes to s = (code − 64)/876: their signal is
/// s·876/1023 + 64/1023. Apple's is the normalized signal itself (GR-16's
/// code domains).
static let videoCodeScale: Float = 876.0 / 1023.0, videoCodeOffset: Float = 64.0 / 1023.0

/// A curve's code domain as the pass's `codeScale` and `codeOffset`. A
/// full-range file decodes to s = code/1023, so Sony's and Panasonic's
/// signal is s itself there (spec §11 GR-22); Apple's is (1, 0) in both,
/// and so is Canon's: its clips are recorded full range and its ProRes
/// reads out full range (spec §11 HD-17 (e)).
static func codeDomain(_ curve: LogCurve, fullRange: Bool) -> (scale: Float, offset: Float) {
    switch curve {
    case .appleLog, .appleLog2: return (1, 0)
    case .slog3, .vlog: return fullRange ? (1, 0) : (videoCodeScale, videoCodeOffset)
    case .canonLog2: return (1, 0)
    case .canonLog3: return (1, 0)
    }
}

/// Published chromaticities (x, y) of red, green and blue: ITU-R BT.709,
/// ITU-R BT.2020, and P3 D65 (SMPTE EG 432-1); the camera gamuts from
/// their makers' documents (GR-16's append): Sony's S-Gamut3.Cine and
/// S-Gamut3, Panasonic's V-Gamut, Apple's Apple Wide Gamut; Canon's Cinema
/// Gamut from the ACES project's Canon CSCs
/// (`canon/CSC.Canon.CLog2_CGamut_to_ACES.ctl` in
/// aces-aswf/aces-input-and-colorspaces, Apache-2.0; spec §11 HD-17 (a)),
/// whose numbers only are cited. Every white is D65.
private static func chromaticities(_ primaries: InputPrimaries) -> [SIMD2<Double>] {
    switch primaries {
    case .bt709: return [[0.640, 0.330], [0.300, 0.600], [0.150, 0.060]]
    case .bt2020: return [[0.708, 0.292], [0.170, 0.797], [0.131, 0.046]]
    case .p3D65: return [[0.680, 0.320], [0.265, 0.690], [0.150, 0.060]]
    case .sGamut3Cine: return [[0.766, 0.275], [0.225, 0.800], [0.089, -0.087]]
    case .sGamut3: return [[0.730, 0.280], [0.140, 0.855], [0.100, -0.050]]
    case .vGamut: return [[0.730, 0.280], [0.165, 0.840], [0.100, -0.030]]
    case .appleWideGamut: return [[0.725, 0.301], [0.221, 0.814], [0.068, -0.076]]
    case .cinemaGamut: return [[0.740, 0.270], [0.170, 1.140], [0.080, -0.100]]
    }
}

private static let d65 = SIMD2<Double>(0.3127, 0.3290)

/// Linear RGB → XYZ for `primaries` and D65, by the standard derivation:
/// each primary's XYZ at Y = 1 as a column, scaled so white sums to D65.
private static func rgbToXYZ(_ primaries: InputPrimaries) -> simd_double3x3 {
    let columns = chromaticities(primaries).map {
        SIMD3<Double>($0.x / $0.y, 1, (1 - $0.x - $0.y) / $0.y)
    }
    let unscaled = simd_double3x3(columns: (columns[0], columns[1], columns[2]))
    let white = SIMD3<Double>(d65.x / d65.y, 1, (1 - d65.x - d65.y) / d65.y)
    let scale = unscaled.inverse * white
    return simd_double3x3(
        columns: (columns[0] * scale.x, columns[1] * scale.y, columns[2] * scale.z))
}

/// Linear `primaries` RGB → linear BT.2020 RGB (spec §11 HD-13), derived
/// like `toBT709`; exactly the identity for BT.2020.
static func toBT2020(from primaries: InputPrimaries) -> simd_float3x3 {
    guard primaries != .bt2020 else { return matrix_identity_float3x3 }
    let m = rgbToXYZ(.bt2020).inverse * rgbToXYZ(primaries)
    return simd_float3x3(rows: (0..<3).map { r in
        SIMD3<Float>((0..<3).map { c in Float(m[c][r]) })

import AppKit

/// What the Camera Log popup can say: none, a built-in curve with its gamut,
/// a `lut` media of the project, or the Use LUT… row that imports one.
enum CameraLogChoice: Equatable {
    case none
    case curve(LogCurve, CameraGamut)
    case lut(UInt32)
    case useLUT

    /// The built-in rows, in the popup's order (spec §11 GR-16): every curve
    /// with each gamut it pairs with.
    static let curves: [CameraLogChoice] = [
        .curve(.appleLog, .bt2020), .curve(.appleLog2, .appleWideGamut),
        .curve(.slog3, .sGamut3Cine), .curve(.slog3, .sGamut3), .curve(.vlog, .vGamut),
        .curve(.canonLog2, .cinemaGamut), .curve(.canonLog2, .bt2020),
        .curve(.canonLog3, .cinemaGamut), .curve(.canonLog3, .bt2020),
    ]

    /// A media's setting as a row: its curve and gamut (the curve's first
    /// when none is stored), else its LUT, else none.
    init(_ color: MediaColor?) {
        if let log = color?.log, let gamut = color?.effectiveGamut {
            self = .curve(log, gamut)
        } else if let lut = color?.lut {
            self = .lut(lut)
        } else {
            self = .none
        }
    }

    /// The row's title: "S-Log3 / S-Gamut3.Cine", "Apple Log" (a curve with
    /// one gamut is named alone), "LUT: <name>".
    func title(in snapshot: ProjectSnapshot) -> String {
        switch self {
        case .none: return "None"
        case .curve(let log, let gamut):
            return log.gamuts.count > 1 || log == .vlog
                ? "\(log.displayName) / \(gamut.displayName)" : log.displayName
        case .lut(let id):
            return "LUT: " + (snapshot.media(id).map(LookGallery.lutName) ?? "media \(id)")
        case .useLUT: return "Use LUT…"
        }
    }
}

/// The Media tab's **Camera Log** section (spec §11 GR-16, §4.3): how the
/// file selected in the list is converted at step 0 — None, a maker's curve,
/// or a `.cube` LUT — one undo step "Camera Log", and a line saying what is
/// set and whether it came from the file. It acts on `selectedMedia`, the row
/// a click selects (`MediaPaneCommands.select(_:)`, which refreshes this
/// section), and is disabled when that is not a video file. The agent's
/// mirror is `set_media_color` (`AgentServer+Media.swift`).
extension MediaPane {
    func cameraLogSection() -> InspectorSection {
        let binding = self.binding
        /// The selected row when it is a video file.
        func selected() -> MediaSnapshot? {
            guard let id = binding.document?.selectedMedia,
                let media = binding.documentSnapshot.media(id), media.kind == .video
            else { return nil }
            return media
        }
        let snapshot = binding.documentSnapshot
        let luts = LookGallery.luts(in: snapshot).map { CameraLogChoice.lut($0.id) }
        let choices = ([CameraLogChoice.none] + CameraLogChoice.curves + luts + [.useLUT])
            .map { (title: $0.title(in: snapshot), value: $0) }
        let popup = OptionPopupControl(
            width: InspectorMetrics.popupWidth + 52, choices: choices,
            read: { CameraLogChoice(selected()?.color) },
            write: { [weak self] choice in
                guard let media = selected(), choice != CameraLogChoice(media.color) else { return }
                // Every write keeps a PQ file's peak override (spec §11 HD-12):
                // `color` replaces the Camera Log and the override together.
                let pq = media.color?.pq
                switch choice {
                case .none:
                    binding.apply(
                        "Camera Log", [.setMediaColor(media: media.id, color: MediaColor(pq: pq))])
                case .curve(let log, let gamut):
                    binding.apply(
                        "Camera Log",
                        [.setMediaColor(
                            media: media.id, color: MediaColor(log: log, gamut: gamut, pq: pq))])
                case .lut(let lut):
                    binding.apply(
                        "Camera Log",
                        [.setMediaColor(media: media.id, color: MediaColor(lut: lut, pq: pq))])
                case .useLUT:
                    self?.inspector?.onCommand?(
                        #selector(EditorViewController.useCameraLogLUT(_:)))
                }
            },
            enabled: { selected() != nil },
            onEdit: { binding.edited() })
        popup.toolTip = "How this file's log footage is converted to Rec. 709"
        let readout = inspectorReadout(width: InspectorMetrics.popupWidth + 52) {
            guard let media = selected() else { return "Select a video in the list" }
            let title = CameraLogChoice(media.color).title(in: binding.documentSnapshot)
            return media.color?.detected == true ? "\(title) — from the file" : title
        }
        return InspectorSection(
            id: "media.camera_log", title: "Camera Log",
            summary: {
                selected().map {
                    CameraLogChoice($0.color).title(in: binding.documentSnapshot)
                }
            },
            rows: [inspectorRow("Log", [popup]), inspectorRow(nil, [readout])])
    }
}
